// One source, several images. What differs between them is a slot letter, a
// version, whether the image is marked provisional (TBYB), and whether it buys
// itself — all build inputs, so the two arms of the experiment are the same
// code with the same bugs, and only the declaration changes.
//
// A generated file rather than `-D` defines, because the version and the TBYB
// flag have to be real consts: they are built into the IMAGE_DEF at compile
// time, which is the only place the ROM will look for them.
use std::{env, fs, path::PathBuf};

fn flag(name: &str, default: bool) -> bool {
    match env::var(name) {
        Ok(v) => matches!(v.as_str(), "1" | "true" | "yes" | "on"),
        Err(_) => default,
    }
}

fn main() {
    let slot = env::var("EXP143_SLOT").unwrap_or_else(|_| "A".to_string());
    let major: u16 = env::var("EXP143_MAJOR").ok().and_then(|v| v.parse().ok()).unwrap_or(1);
    let minor: u16 = env::var("EXP143_MINOR").ok().and_then(|v| v.parse().ok()).unwrap_or(0);
    // Provisional, and buying. Both default off, so a plain `cargo build`
    // produces an ordinary, permanent, bootable image.
    let tbyb = flag("EXP143_TBYB", false);
    let buy = flag("EXP143_BUY", false);

    let out = PathBuf::from(env::var_os("OUT_DIR").unwrap());
    let body = format!(
        "// generated by build.rs — do not edit\n\
         pub const SLOT: &str = {slot:?};\n\
         pub const VERSION_MAJOR: u16 = {major};\n\
         pub const VERSION_MINOR: u16 = {minor};\n\
         /// Is this image marked try-before-you-buy in its own IMAGE_DEF?\n\
         pub const TBYB: bool = {tbyb};\n\
         /// If it is provisional, does it call `explicit_buy` — or refuse?\n\
         pub const BUY: bool = {buy};\n"
    );
    fs::write(out.join("exp143_config.rs"), body).unwrap();

    for var in ["EXP143_SLOT", "EXP143_MAJOR", "EXP143_MINOR", "EXP143_TBYB", "EXP143_BUY"] {
        println!("cargo:rerun-if-env-changed={var}");
    }
    println!("cargo:rerun-if-changed=build.rs");
}
